const documentos = JSON.parse($json.output);

const aprobado = documentos.every(doc => doc.valido === true);
const rechazados = documentos.filter(doc => doc.valido === false);

let descripcion = "";

if (aprobado) {
  descripcion = "Todos los documentos son válidos y fueron aprobados.";
} else {
  for (const rec of rechazados) {
    descripcion += `Documento: ${rec.nombre}. Estado: ${rec.valido}. Razón: ${rec.razon}\n`;
  }
}

return [
  {
    json: {
      aprobado,
      descripcion
    }
  }
];

// Extraer número de encargo con múltiples patrones posibles
function extraerNumeroEncargo(texto) {
  const patrones = [
    /Numero\s+Encargo\s+([A-Z0-9][A-Z0-9\-]+)/i,
    /N[uú]mero\s+de\s+Encargo\s+([A-Z0-9][A-Z0-9\-]+)/i,
    /Encargo\s*N[°º]?\s*[:\s]+([A-Z0-9][A-Z0-9\-]+)/i,
    /N[°º]\s*Encargo\s*[:\s]+([A-Z0-9][A-Z0-9\-]+)/i,
  ];

  for (const patron of patrones) {
    const match = texto.match(patron);
    if (match) return match[1].trim();
  }

  return null;
}

const items = $input.first().json.data;

let ordenDeGiro = '', numeroEncargo = '';
const anexos = [];


for (const item of items) {
  const filename = (item.info?.Title || item.info?.Creator || '').toLowerCase();
  const texto = item.text || '';

  // Identificar la orden de giro por el contenido del texto
  if (texto.toLowerCase().includes('formato orden de giro')) {
    numeroEncargo = extraerNumeroEncargo(texto);
    ordenDeGiro = `--- ORDEN DE GIRO ---\n${texto}`;
  } else {
    const nombreAnexo = item.info?.Title || item.info?.Author || 'Anexo';
    anexos.push(`--- ANEXO: ${nombreAnexo} ---\n${texto}`);
  }
}

const prompt = `=== ORDEN DE GIRO ===
${ordenDeGiro}

=== ANEXOS ===
${anexos.join('\n\n')}`;

return [{ json: { prompt, numeroEncargo } }];

// Toma el ítem agregado y separa cada binario en su propio ítem
const item = $input.first();
const binaryData = item.binary;

const result = [];
for (const key of Object.keys(binaryData)) {
  result.push({
    json: { fieldName: key, fileName: binaryData[key].fileName },
    binary: { data: binaryData[key] }  // siempre llamado "data" para el siguiente nodo
  });
}

return result;
